begin;
select plan(34);
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in ('private.client_weekly_versions'::regclass,'private.client_weekly_exceptions'::regclass,'private.client_weekly_operations'::regclass)),'weekly stores force RLS');
select ok(not has_table_privilege('authenticated','private.client_weekly_versions','select,insert,update,delete'),'no direct authenticated weekly access');
select ok(not has_table_privilege('service_role','private.client_weekly_operations','select,insert,update,delete'),'no service role operation bypass');
select ok(not has_function_privilege('authenticated','private.client_weekly_days(uuid,date,integer)','execute'),'raw projection helper cannot be called by authenticated');
select ok(not (select prosecdef from pg_proc where oid='public.save_client_weekly(uuid,uuid,jsonb)'::regprocedure),'public write wrapper is invoker');
set local role anon;
select throws_ok($$select public.client_weekly_snapshot(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),current_date)$$,'42501',null,'anonymous read denied');
reset role;
select set_config('test.weekly_amr',floor(extract(epoch from clock_timestamp()-interval '2 minutes'))::text,true);
insert into auth.users(id,aud,role,email,email_confirmed_at,created_at,updated_at) values('c2100000-0000-4000-8000-000000000001','authenticated','authenticated','weekly-manager@example.invalid',now(),now(),now());
insert into auth.identities(id,provider_id,user_id,identity_data,provider) values(gen_random_uuid(),'weekly-manager','c2100000-0000-4000-8000-000000000001','{"sub":"weekly-manager","email":"weekly-manager@example.invalid","email_verified":true}','google');
insert into auth.sessions(id,user_id,created_at,aal) values('c2200000-0000-4000-8000-000000000001','c2100000-0000-4000-8000-000000000001',now()-interval '3 minutes','aal2');
insert into auth.mfa_amr_claims(id,session_id,created_at,updated_at,authentication_method)
select gen_random_uuid(),'c2200000-0000-4000-8000-000000000001',to_timestamp(current_setting('test.weekly_amr')::bigint),to_timestamp(current_setting('test.weekly_amr')::bigint),method from unnest(array['oauth','totp'])method;
insert into public.organizations(id,code,name) values('c2300000-0000-4000-8000-000000000001','weekly-synthetic','合成機構');
insert into public.branches(id,organization_id,code,name) values('c2400000-0000-4000-8000-000000000001','c2300000-0000-4000-8000-000000000001','main','合成分支');
insert into public.profiles(id,display_name,kind) values('c2100000-0000-4000-8000-000000000001','合成主管','staff');
insert into public.memberships(id,organization_id,branch_id,profile_id,status,starts_at) values('c2500000-0000-4000-8000-000000000001','c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','c2100000-0000-4000-8000-000000000001','active',now()-interval '1 year');
insert into public.membership_roles(membership_id,role_id) values('c2500000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000003');
insert into public.clients(id,organization_id,branch_id,client_code,display_name,admitted_on) values('c2600000-0000-4000-8000-000000000001','c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','C-1','合成個案',(now() at time zone 'Asia/Taipei')::date);
insert into private.reauth_challenges(id,user_id,session_id,nonce_sha256,idempotency_key,issued_jwt_iat,created_at,expires_at,consumed_at,consumed_jwt_iat,factor_method,factor_verified_at)
values('c2700000-0000-4000-8000-000000000001','c2100000-0000-4000-8000-000000000001','c2200000-0000-4000-8000-000000000001',repeat('1',64),gen_random_uuid(),now()-interval '2 minutes',now()-interval '2 minutes',now()+interval '5 minutes',now()-interval '1 minute',now()-interval '1 minute','totp',now()-interval '1 minute');
insert into private.reauth_events(user_id,session_id,challenge_id,aal,verification_method,verified_at) values('c2100000-0000-4000-8000-000000000001','c2200000-0000-4000-8000-000000000001','c2700000-0000-4000-8000-000000000001','aal2','totp',now()-interval '1 minute');
select set_config('request.jwt.claims',jsonb_build_object('sub','c2100000-0000-4000-8000-000000000001','session_id','c2200000-0000-4000-8000-000000000001','role','authenticated','aud','authenticated','aal','aal2','is_anonymous',false,'email','weekly-manager@example.invalid','iat',floor(extract(epoch from now())),'exp',floor(extract(epoch from now()+interval '30 minutes')),'amr',jsonb_build_array(jsonb_build_object('method','oauth','timestamp',current_setting('test.weekly_amr')::bigint),jsonb_build_object('method','totp','timestamp',current_setting('test.weekly_amr')::bigint)))::text,true);
create function pg_temp.weekly_day(p_weekday integer,p_attending boolean default true) returns jsonb language sql as $$ select jsonb_build_object('weekday',p_weekday,'attending',p_attending,'startsAt',case when p_attending then '09:00' else null end,'endsAt',case when p_attending then '16:00' else null end,'outbound',null,'inbound',null); $$;
create function pg_temp.weekly_input(p_overrides jsonb default '{}') returns jsonb language sql as $$ select jsonb_build_object('action','save_plan','clientId','c2600000-0000-4000-8000-000000000001','expectedVersion',0,'idempotency_key','c2800000-0000-4000-8000-000000000001','plan',jsonb_build_object('effectiveFrom',(now() at time zone 'Asia/Taipei')::date,'effectiveTo',null,'reason','已確認合成週表','days',(select jsonb_agg(pg_temp.weekly_day(n)) from generate_series(1,7)n)))||p_overrides; $$;
create function pg_temp.weekly_save(p_input jsonb default pg_temp.weekly_input()) returns jsonb language sql as $$ select receipt from public.save_client_weekly('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001',p_input); $$;
create function pg_temp.weekly_read() returns jsonb language sql as $$ select payload from public.client_weekly_snapshot('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','c2600000-0000-4000-8000-000000000001',(now() at time zone 'Asia/Taipei')::date); $$;
create function pg_temp.weekly_exception(p_attending boolean default false,p_version integer default 0) returns jsonb language sql as $$ select jsonb_build_object('action','save_exception','clientId','c2600000-0000-4000-8000-000000000001','expectedVersion',p_version,'idempotency_key',gen_random_uuid(),'serviceDate',(now() at time zone 'Asia/Taipei')::date,'day',pg_temp.weekly_day(extract(isodow from now() at time zone 'Asia/Taipei')::integer,p_attending),'reason','合成單日異動'); $$;
set local role authenticated;
select throws_ok($$select pg_temp.weekly_save()$$,'42501',null,'nonadmitted Google account cannot write');
reset role;
insert into private.executive_access_policy(allowed_user_id,allowed_email,google_subject,enabled,approval_reference) values('c2100000-0000-4000-8000-000000000001','weekly-manager@example.invalid','weekly-manager',true,'synthetic weekly test');
set local role authenticated;
select is(pg_temp.weekly_read()->>'version','0','empty snapshot has no fabricated plan');
select is(pg_temp.weekly_save()->>'version','1','authorized plan version one saved');
select is(pg_temp.weekly_save()->>'replayed','true','same input replay is safe');
select throws_ok($$select pg_temp.weekly_save(jsonb_set(pg_temp.weekly_input(),'{plan,reason}','"不同週表依據"'))$$,'23505',null,'changed input with same operation key conflicts');
select throws_ok($$select pg_temp.weekly_save(pg_temp.weekly_input(jsonb_build_object('idempotency_key',gen_random_uuid())))$$,'40001',null,'stale base version rejected');
select is(jsonb_array_length(pg_temp.weekly_read()->'days'),28,'snapshot has 28 exact dates');
select is((select count(*)::integer from jsonb_array_elements(pg_temp.weekly_read()->'days')d where d->>'status'='scheduled'),28,'recurrence projects expected attendance');
select lives_ok($$select pg_temp.weekly_save(pg_temp.weekly_exception())$$,'single day cancellation is append-only');
select is(pg_temp.weekly_read()->'days'->0->>'status','cancelled','single day cancellation removes expected attendance');
select is(pg_temp.weekly_read()->'days'->1->>'status','scheduled','single day does not modify other dates');
select lives_ok($$select pg_temp.weekly_save(pg_temp.weekly_exception(true,1))$$,'single day reinstatement is a new exception version');
select is(pg_temp.weekly_read()->'days'->0->>'exceptionVersion','2','projection points at latest exception');
select throws_ok($$select public.client_weekly_snapshot('c2300000-0000-4000-8000-000000000001',gen_random_uuid(),'c2600000-0000-4000-8000-000000000001',current_date)$$,'42501',null,'cross branch snapshot denied');
select throws_ok($$select pg_temp.weekly_save(jsonb_set(pg_temp.weekly_input(jsonb_build_object('expectedVersion',1,'idempotency_key',gen_random_uuid())),'{plan,effectiveFrom}',to_jsonb(((now() at time zone 'Asia/Taipei')::date-1)::text)))$$,'22023',null,'new plan cannot retroactively alter historical dates');
select throws_ok($$select pg_temp.weekly_save(jsonb_set(pg_temp.weekly_input(jsonb_build_object('expectedVersion',1,'idempotency_key',gen_random_uuid())),'{plan,days,0,startsAt}','"25:00"'))$$,'22023',null,'direct RPC rejects invalid time');
select throws_ok($$select pg_temp.weekly_save(jsonb_set(pg_temp.weekly_input(jsonb_build_object('expectedVersion',1,'idempotency_key',gen_random_uuid())),'{plan,days,0,weekday}','2'))$$,'22023',null,'direct RPC rejects duplicate weekdays');
reset role;
select throws_ok($$update private.client_weekly_versions set version=7$$,'55000',null,'stored plan history is immutable');
select is((select count(*)::integer from private.client_weekly_versions),1,'replays and invalid writes do not create extra plans');
select is((select count(*)::integer from private.client_weekly_exceptions),2,'exceptions retain prior version');
select is((select count(*)::integer from public.attendance_records where client_id='c2600000-0000-4000-8000-000000000001'),0,'planned arrival never creates attendance evidence');
insert into public.clients(id,organization_id,branch_id,client_code,display_name,status,admitted_on)
values('c2600000-0000-4000-8000-000000000002','c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','C-2','合成暫停個案','suspended',(now() at time zone 'Asia/Taipei')::date),
('c2600000-0000-4000-8000-000000000003','c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','C-3','合成未收案個案','active',null);
create function pg_temp.weekly_read_other(p_client uuid) returns jsonb language sql as $$ select payload from public.client_weekly_snapshot('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001',p_client,(now() at time zone 'Asia/Taipei')::date); $$;
set local role authenticated;
select pg_temp.weekly_save(pg_temp.weekly_exception(true)||jsonb_build_object('clientId','c2600000-0000-4000-8000-000000000002'));
select is(pg_temp.weekly_read_other('c2600000-0000-4000-8000-000000000002')->'days'->0->>'status','inactive','suspension suppresses even explicit add-day intent');
select is(pg_temp.weekly_read_other('c2600000-0000-4000-8000-000000000002')->'days'->0->'day','null'::jsonb,'inactive clients create no transport demand');
select is(pg_temp.weekly_read_other('c2600000-0000-4000-8000-000000000003')->'days'->0->>'status','not_admitted','pending admission is not an expected attendee');
select is((select payload->>'evidenceKind' from public.client_weekly_projection('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001',(now() at time zone 'Asia/Taipei')::date)),'planned_not_attended','branch projection identifies planned evidence only');
reset role;
select ok(exists(select 1 from public.audit_events where table_name='client_weekly_snapshot') and exists(select 1 from public.audit_events where table_name='client_weekly_versions'),'weekly reads and writes produce minimal audit records');
select ok(not exists(select 1 from public.audit_events where table_name like 'client_weekly%' and metadata::text like '%合成%'),'audit metadata does not contain contact or clinical text');
update public.memberships set status='suspended' where id='c2500000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.weekly_read()$$,'42501',null,'suspended membership cannot read its former scope');
reset role;
select * from finish();
rollback;
